/** Full badge token as generated by create_floor_worker: "vp_badge_" + 48 hex characters. */
const BADGE_RE = /vp_badge_[0-9a-f]{48}/i;

/**
 * Pulls a badge token out of whatever a scanner produced: the bare token, a URL
 * containing it, or text with stray prefixes/suffixes (some scanners add them).
 * Returns null when there is no complete token.
 */
export function extractBadgeToken(text: string): string | null {
  const match = text.match(BADGE_RE);
  return match ? match[0].toLowerCase() : null;
}
